{"function": "() => {
    const table = document.querySelector('table');
    const rows = Array.from(table.rows);
    const data = [];
    let totalMen = 0, totalWomen = 0, totalTotal = 0;
    for (let i = 1; i < rows.length; i++) {
        const cells = rows[i].cells;
        if (cells.length >= 5) {
            const ioc = cells[0].innerText.trim();
            const country = cells[1].innerText.trim();
            const men = parseInt(cells[2].innerText.trim());
            const women = parseInt(cells[3].innerText.trim());
            const total = parseInt(cells[4].innerText.trim());
            // check if it's the total row
            if (country === 'Total') {
                console.log('Total row:', men, women, total);
                continue;
            }
            data.push({ioc, country, men, women, total});
            totalMen += men;
            totalWomen += women;
            totalTotal += total;
        }
    }
    // sort by country name
    data.sort((a, b) => a.country.localeCompare(b.country));
    // also get the total row from table footer
    const totalRow = rows[rows.length - 1];
    const totalCells = totalRow.cells;
    const reportedMen = parseInt(totalCells[2].innerText.trim());
    const reportedWomen = parseInt(totalCells[3].innerText.trim());
    const reportedTotal = parseInt(totalCells[4].innerText.trim());
    return {
        data,
        totals: { totalMen, totalWomen, totalTotal },
        reported: { reportedMen, reportedWomen, reportedTotal },
        count: data.length
    };
}"}

